<script setup>
import { ref, onMounted, onUnmounted } from 'vue'

const canvasRef = ref(null)
let animationId = null

// Characters: Japanese katakana + digits + Latin letters
const CHAR_SET = 'アイウエオカキクケコサシスセソタチツテトナニヌネノハヒフヘホマミムメモヤユヨラリルレロワヲン0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz!@#$%^&*()_+-=[]{}|;:,.<>?/~`ABCDEFGHIJKLMNOPQRSTUVWXYZ'

// Configuration
const FONT_SIZE = 14
const COLUMN_GAP = 18
const FADE_SPEED = 0.05
const DRAW_INTERVAL = 33 // ~30fps for the rain (performance optimization)

function getChar() {
  return CHAR_SET[Math.floor(Math.random() * CHAR_SET.length)]
}

onMounted(() => {
  const canvas = canvasRef.value
  if (!canvas) return

  const ctx = canvas.getContext('2d')
  let columns = []
  let lastTime = 0

  function resize() {
    canvas.width = window.innerWidth
    canvas.height = window.innerHeight
    initColumns()
  }

  function initColumns() {
    const colCount = Math.floor(canvas.width / COLUMN_GAP)
    columns = []
    for (let i = 0; i < colCount; i++) {
      columns.push({
        x: i * COLUMN_GAP,
        y: Math.random() * canvas.height * -1,
        speed: 0.5 + Math.random() * 2.5,
        chars: [],
        length: 8 + Math.floor(Math.random() * 25),
        active: true,
      })
    }
  }

  function draw(timestamp) {
    if (timestamp - lastTime < DRAW_INTERVAL) {
      animationId = requestAnimationFrame(draw)
      return
    }
    lastTime = timestamp

    // Semi-transparent black to create fade trail
    ctx.fillStyle = 'rgba(0, 0, 0, 0.05)'
    ctx.fillRect(0, 0, canvas.width, canvas.height)

    ctx.font = `${FONT_SIZE}px "Courier New", Consolas, monospace`

    columns.forEach(col => {
      if (!col.active) return

      // Draw the head character (brightest - white-green)
      const headY = Math.round(col.y)
      if (headY > 0 && headY < canvas.height) {
        // Head char - bright white-green
        ctx.fillStyle = '#AAFFAA'
        ctx.shadowColor = '#00FF41'
        ctx.shadowBlur = 8
        ctx.fillText(getChar(), col.x, headY)
        ctx.shadowBlur = 0
      }

      // Draw trail characters with decreasing brightness
      for (let j = 1; j < col.length; j++) {
        const trailY = headY - j * FONT_SIZE
        if (trailY > 0 && trailY < canvas.height) {
          const alpha = 1 - (j / col.length)
          const brightness = Math.floor(alpha * 255)
          ctx.fillStyle = `rgb(0, ${brightness}, ${Math.floor(brightness * 0.25)})`

          // Randomly mutate characters in the trail
          if (Math.random() > 0.97) {
            ctx.fillStyle = `rgba(0, 255, 65, ${alpha})`
          }

          ctx.fillText(getChar(), col.x, trailY)
        }
      }

      // Move column down
      col.y += col.speed * COLUMN_GAP * 0.12

      // Reset when off screen
      if (col.y - col.length * FONT_SIZE > canvas.height) {
        col.y = Math.random() * canvas.height * -0.5
        col.speed = 0.5 + Math.random() * 2.5
        col.length = 8 + Math.floor(Math.random() * 25)
      }
    })

    animationId = requestAnimationFrame(draw)
  }

  resize()
  window.addEventListener('resize', resize)
  animationId = requestAnimationFrame(draw)

  onUnmounted(() => {
    if (animationId) cancelAnimationFrame(animationId)
    window.removeEventListener('resize', resize)
  })
})
</script>"}

