  if (!cmd.trim()) {
    showInput.value = true
    return
  }

  const responseLines = getCommandResponse(cmd)

  if (responseLines[0] === '__CLEAR__') {
    displayedLines.splice(0, displayedLines.length)
    showInput.value = true
    return
  }

  await sleep(200)
  for (const line of responseLines) {
    addLine(line, '', line.startsWith('>') || line.startsWith('█') ? 'text-matrix-green' : 'text-matrix-dim')
    await sleep(60 + Math.random() * 80)
    triggerGlitch()
  }

  await sleep(100)
  showInput.value = true
}

