  emit('button-click', btn.action)
  triggerGlitch()

  const cmd = btn.action
  typeCommand(btn.label).then(() => {
    processCommand(cmd)
  })
}

function handleBgClick() {
  // Easter egg: clicking background triggers glitch
  triggerGlitch()
}

// Keyboard input
function handleKeydown(e) {
  if (!showInput.value) return

  if (e.key === 'Enter') {
    const cmd = currentInput.value
    displayedLines.push({
      text: cmd,
      prefix: props.prompt,
      textClass: 'text-matrix-green'
    })
    currentInput.value = ''
    processCommand(cmd)
  } else if (e.key === 'Backspace') {
    currentInput.value = currentInput.value.slice(0, -1)
  } else if (e.key.length === 1 && !e.ctrlKey && !e.metaKey) {
    currentInput.value += e.key
  }
}

// Clock
let clockInterval = null
function updateClock() {
  const now = new Date()
  currentTime.value = now.toLocaleTimeString('en-US', { hour12: false }) + ' UTC'
}

// Random glitch interval
let glitchInterval = null

onMounted(async () => {
  window.addEventListener('keydown', handleKeydown)
  updateClock()
  clockInterval = setInterval(updateClock, 1000)

  // Random periodic glitch
  glitchInterval = setInterval(() => {
    if (Math.random() > 0.7) triggerGlitch()
  }, 4000)

  // Boot sequence
  await sleep(800)
  for (const line of bootSequence) {
    addLine(line.text, line.prefix || '', line.textClass || 'text-matrix-green')
    await sleep(line.delay)
  }

  bootComplete.value = true
  showButtons.value = true
  await sleep(200)
  showInput.value = true
})

onUnmounted(() => {
  window.removeEventListener('keydown', handleKeydown)
  if (clockInterval) clearInterval(clockInterval)
  if (glitchInterval) clearInterval(glitchInterval)
})
